"""Entrega consolidada e previa dos apoios em coordenadas do mundo."""
from coxa_v6 import *
def deliver():
    old=ROOT/'public/assets/lutadores/coxa/revisao-v5';shutil.copytree(old,DEST,dirs_exist_ok=True)
    manifest=read(old/'manifest-art.json');manifest.update(version=6,previousVersion='../revisao-v5/manifest-art.json',revision='Andador avanca antes dos dois passos; recuo de dois passos precede o transporte do andador.')
    cards=[];cfg={}
    for action,title in [('walk-forward','Avançar: andador → passo direito → passo esquerdo'),('walk-backward','Recuar: passo esquerdo → passo direito → andador')]:
        f=OUT/'normal'/action;r=read(f/'report.json');rig=read(f/'attachments.json');e=next(x for x in manifest['body'] if x['skin']=='normal' and x['action']==action)
        for src,key in [('aligned-body-sheet.png','body'),('composed-sheet.png','composed'),('attachments.json','rig')]:shutil.copy2(f/src,DEST/e[key])
        motion='normal/'+action+'-motion.json';shutil.copy2(f/'motion-guide.json',DEST/motion)
        e.update(frames=12,fpsProposed=10,sourceRevision=6,source_sha256=r['source_sha256'],references=r['references'],attachments=rig,assemblySources=[],motionGuide=motion,rootMotionRequired=True,status='Arte e previa com apoios por fase; integracao de combate pendente.',visualBoxes=[list(Image.open(f/f'composed-{i:02}.png').getbbox()) for i in range(12)])
        e['body_sha256']=sha(DEST/e['body']);e['composed_sha256']=sha(DEST/e['composed'])
        e['assemblySources']=[{'frame':a['frame'],'source':a['bodySource'],'sha256':a['source_sha256'],'sourceFrame':a['bodySourceFrame']} for a in rig]
        cards.append(f'<article><h2>{title}</h2><canvas id="{action}" width="1024" height="680"></canvas><p><button onclick="step(\'{action}\',-1)">◀</button> <button onclick="toggle(\'{action}\')">Pausar / reproduzir</button> <button onclick="step(\'{action}\',1)">▶</button> <span id="p-{action}"></span></p><a href="normal/{action}/world-preview.gif">GIF com chão fixo</a> · <a href="normal/{action}/composed-sheet.png">Folha com andador</a><details><summary>Todos os quadros</summary><img src="normal/{action}/composed-contact.png"></details></article>')
        cfg[action]={'phases':rig,'delta':rig[-1]['rootX']}
    manifest['bodyFrames']=sum(e['frames'] for e in manifest['body']);save(DEST/'manifest-art.json',manifest);save(OUT/'manifest-art.json',manifest)
    page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Coxa — andador e passos v6</title><style>body{font:16px system-ui;background:#20252b;color:#eee;max-width:1100px;margin:32px auto;padding:0 20px}article{background:#303740;padding:20px;margin:24px 0;border-radius:12px}h1{font-size:28px}h2{font-size:20px}canvas,img{width:100%;image-rendering:pixelated}button,select{font:inherit;padding:7px}a{color:#9ee0b5}details{margin-top:14px}</style><h1>Coxa normal — andador como apoio da caminhada</h1><p>Avançar: levantar, avançar e plantar o andador; depois dois passos curtos.<br>Recuar: dois passos curtos para trás; depois levantar e trazer o andador.</p><p>As marcas do chão ficam paradas para conferir o apoio. As duas mãos seguem as manoplas; o objeto permanece rígido.</p><p>Velocidade <select id="speed"><option value="1">Normal</option><option value="0.5">Metade</option><option value="0.25">Um quarto</option></select> · <a href="coxa-revisao-v6.zip">Pacote completo atualizado</a></p>'''+''.join(cards)+'''<p>12 quadros por caminhada, 10 FPS propostos. Postura parada preservada da v5. A futura integração precisa respeitar as fases de deslocamento registradas; a arte ainda não está integrada ao combate.</p><script>const cfg='''+json.dumps(cfg,ensure_ascii=False)+''';const states={};for(const[id,c]of Object.entries(cfg)){const im=new Image();im.src='normal/'+id+'/composed-sheet.png';states[id]={...c,im,i:0,cycle:0,play:true,t:0}}function draw(id){const s=states[id],p=s.phases[s.i],c=document.getElementById(id).getContext('2d');c.setTransform(2,0,0,2,0,0);c.imageSmoothingEnabled=false;c.fillStyle='#303740';c.fillRect(0,0,512,340);c.strokeStyle='#87908a';c.beginPath();c.moveTo(0,293);c.lineTo(512,293);for(let x=0;x<512;x+=18){c.moveTo(x,294);c.lineTo(x,300)}c.stroke();if(s.im.complete)c.drawImage(s.im,s.i%5*512,Math.floor(s.i/5)*320,512,320,40+s.cycle*s.delta+p.rootX,0,512,320);document.getElementById('p-'+id).textContent=(s.i+1)+'/12 — '+p.phase}function step(id,d){const s=states[id];s.play=false;s.cycle=0;s.i=(s.i+d+12)%12;draw(id)}function toggle(id){states[id].play=!states[id].play}function tick(t){for(const[id,s]of Object.entries(states)){if(s.play&&t-s.t>=100/+document.getElementById('speed').value){s.i++;if(s.i===12){s.i=0;s.cycle=(s.cycle+1)%3}s.t=t}draw(id)}requestAnimationFrame(tick)}requestAnimationFrame(tick);</script></html>'''
    (OUT/'revisao.html').write_text(page,encoding='utf-8')
    with zipfile.ZipFile(OUT/'coxa-revisao-v6.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in DEST.rglob('*'):
            if p.is_file():z.write(p,p.relative_to(DEST))
    print(json.dumps({'actions':36,'frames':manifest['bodyFrames'],'replaced':2}))
if __name__=='__main__':deliver()
